+		long both = 0;
+		long baselineOnly = 0;
+		long candidateOnly = 0;
+		long index = 0;
+		for (List<Object> canonicalKey : union) {
+			Group left = baseline.get(canonicalKey);
+			Group right = candidate.get(canonicalKey);
