+				for (IItem item : iterable) {
+					if (count >= max) {
+						sb.append("... (truncated at ").append(max).append(" points)\n");
+						return sb.toString();
+					}
+					IQuantity time = timeAccessor != null ? timeAccessor.getMember(item) : null;
+					sb.append(time != null ? JfrToolkit.formatQuantity(time) : "?");
+					sb.append(", ").append(JfrToolkit.format(valueAccessor.getMember(item))).append("\n");
+					count++;
+				}
+			}
+			return sb.toString();
+		} catch (Exception e) {
+			return "Error: " + JfrToolkit.describeError(e);
+		}
+	}
+
+	private static void appendHeader(StringBuilder sb, List<IAttribute<?>> columns) {
+		for (int i = 0; i < columns.size(); i++) {
+			if (i > 0) {
+				sb.append("\t");
+			}
+			sb.append(columns.get(i).getName());
+		}
+		sb.append("\n");
+	}
+
+	private static List<IAttribute<?>> selectColumns(IType<IItem> type, List<String> requestedColumns) {
+		List<IAttribute<?>> allAttrs = type.getAttributes();
+		if (requestedColumns == null || requestedColumns.isEmpty()) {
+			return allAttrs;
+		}
+		List<IAttribute<?>> selected = new ArrayList<>();
+		for (String colId : requestedColumns) {
+			for (IAttribute<?> attr : allAttrs) {
+				if (attr.getIdentifier().equals(colId)) {
+					selected.add(attr);
+					break;
+				}
+			}
+		}
+		// May be empty: types carrying none of the requested columns get a skip note instead of
+		// rows, so a cross-type query never dumps columns the caller did not ask for.
+		return selected;
+	}
+
+	/**
+	 * Names the event types whose rows are omitted because they carry none of the requested
+	 * columns, with their event counts, so the caller can tell skipped data from absent data.
+	 */
+	private static void appendSkippedTypes(StringBuilder sb, IItemCollection items, List<String> requestedColumns) {
+		if (requestedColumns == null || requestedColumns.isEmpty()) {
+			return;
+		}
+		JfrToolkit.countByEventType(items).forEach((type, count) -> {
+			if (selectColumns(type, requestedColumns).isEmpty()) {
+				sb.append("(").append(type.getIdentifier())
+						.append(": none of the requested columns exist on this type, ").append(count)
+						.append(" events not shown; use getAttributes to list its identifiers)\n");
+			}
+		});
+	}
+
+	private static void appendTypeSummary(StringBuilder sb, IItemCollection items) {
+		Map<IType<IItem>, Long> counts = JfrToolkit.countByEventType(items);
+		if (counts.size() > 1) {
+			sb.append("Matched ").append(counts.size()).append(" event types:\n");
+			counts.forEach((type, count) -> sb.append("  ").append(type.getIdentifier()).append(": ").append(count)
+					.append(" events\n"));
+			sb.append("\n");
+		}
+	}
+
+	private static List<String> findUnknownColumns(IItemCollection items, List<String> requestedColumns) {
+		if (requestedColumns == null || requestedColumns.isEmpty()) {
+			return List.of();
+		}
+		Set<String> available = new HashSet<>();
+		for (IItemIterable iterable : items) {
+			for (IAttribute<?> attr : iterable.getType().getAttributes()) {
+				available.add(attr.getIdentifier());
+			}
+		}
+		return requestedColumns.stream().filter(c -> !available.contains(c)).toList();
+	}
+
+	private static List<String> parseColumns(String columns) {
+		if (columns == null || columns.isBlank()) {
+			return null;
+		}
+		return Arrays.stream(columns.split(",")).map(String::trim).filter(s -> !s.isEmpty()).toList();
+	}
