+		IItemCollection merged = ItemCollectionToolkit.merge(() -> Stream.of(withVehicle, withoutVehicle));
+		assertEquals(
+				Map.of(withVehicle.iterator().next().getType(), 2L, withoutVehicle.iterator().next().getType(), 3L),
